<script setup lang="ts">
import { ref } from 'vue'
import { api, post, query, money } from '../lib/api'
import { isAdmin, selectedDate, campusOptions, defaultCampusId } from '../lib/state'
import { useResource, loadStudents, openDialog, studentOptions } from '../lib/ui'
import type { ClassRoom, Course, Enrollment, Schedule } from '../lib/types'
import PageHeader from '../components/PageHeader.vue'
import AppIcon from '../components/AppIcon.vue'
import LoadState from '../components/LoadState.vue'
const tab=ref('schedules');const students=useResource(loadStudents)
const {data,loading,error,refresh}=useResource(async()=>{const [courses,schedules,classes,enrollments]=await Promise.all([api<Course[]>('/courses'),api<Schedule[]>(`/schedules${query({date:selectedDate.value})}`),api<ClassRoom[]>('/classes'),api<Enrollment[]>('/enrollments')]);return {courses,schedules,classes,enrollments}},[selectedDate])
async function schedule() {
  if(await openDialog({title:'新增课程排课',description:'到校学生离校时，系统将按启用排课与有效报名结算课时。',fields:[{key:'courseId',label:'课程',type:'select',required:true,options:(data.value?.courses||[]).filter(c=>c.enabled).map(c=>({value:c.id,label:`${c.name}${c.campusName ? ` · ${c.campusName}` : ''}`}))},{key:'classId',label:'班级',type:'select',required:true,options:(data.value?.classes||[]).map(c=>({value:c.id,label:`${c.name}${c.campusName ? ` · ${c.campusName}` : ''}`}))},{key:'date',label:'上课日期',type:'date',required:true},{key:'startTime',label:'开始时间',type:'time',required:true},{key:'endTime',label:'结束时间',type:'time',required:true},{key:'units',label:'消耗课时',type:'number',min:0.01,step:0.01,required:true}],initial:{date:selectedDate.value,startTime:'16:00',endTime:'18:00',units:1},submit:v=>{const course=data.value?.courses.find(c=>c.id===Number(v.courseId));const cls=data.value?.classes.find(c=>c.id===Number(v.classId));if(course?.campusId!==cls?.campusId)throw new Error('课程和班级必须属于同一校区');if(v.endTime<=v.startTime)throw new Error('结束时间应晚于开始时间');return post('/schedules',v)},success:'排课已创建'}))refresh()
}
async function enroll() {
  if(await openDialog({title:'学生课程报名',description:'报名将建立对应课程的独立课时账户；重复报名不会重复开户。',fields:[{key:'studentId',label:'学生',type:'select',required:true,options:studentOptions(students.data.value||[])},{key:'courseId',label:'报名课程',type:'select',required:true,options:(data.value?.courses||[]).filter(c=>c.enabled).map(c=>({value:c.id,label:`${c.name}${c.campusName ? ` · ${c.campusName}` : ''}`}))}],submit:v=>{const student=students.data.value?.find(s=>s.id===Number(v.studentId));const course=data.value?.courses.find(c=>c.id===Number(v.courseId));if(student?.campusId!==course?.campusId)throw new Error('学生与课程必须属于同一校区');return post('/enrollments',v)},success:'课程报名成功'}))refresh()
}
async function course() {
  if(await openDialog({title:'创建机构课程',fields:[{key:'campusId',label:'所属校区',type:'select',required:true,options:campusOptions.value},{key:'name',label:'课程名称',required:true},{key:'type',label:'课程类型',type:'select',required:true,options:[{value:'EVENING',label:'晚辅课程'},{value:'HOLIDAY',label:'假期课程'},{value:'WEEKEND',label:'周末课程'}]},{key:'unit',label:'计费单位',type:'select',required:true,options:['次','节','小时'].map(v=>({value:v,label:v}))},{key:'priceYuan',label:'课程单价（元）',type:'number',min:0,step:0.01,required:true},{key:'warningThreshold',label:'余额预警阈值',type:'number',min:0,step:0.01,required:true}],initial:{campusId:defaultCampusId.value,type:'EVENING',unit:'次',priceYuan:100,warningThreshold:3},submit:({priceYuan,...v})=>post('/courses',{...v,price:Math.round(priceYuan*100)}),success:'课程创建成功'}))refresh()
}
</script>
<template><PageHeader title="课程排课" subtitle="安排好学习的节奏，让每一份陪伴有迹可循。"><button v-if="isAdmin" class="btn secondary" @click="course"><AppIcon name="BookPlus" :size="17" />创建课程</button><button v-if="isAdmin" class="btn secondary" @click="enroll"><AppIcon name="UserRoundPlus" :size="17" />学生报名</button><button v-if="isAdmin" class="btn primary" @click="schedule"><AppIcon name="CalendarPlus" :size="17" />新增排课</button></PageHeader><section class="panel"><div class="filter-bar"><div class="tabs"><button :class="{active:tab==='schedules'}" @click="tab='schedules'">每日排课</button><button :class="{active:tab==='courses'}" @click="tab='courses'">课程目录</button><button :class="{active:tab==='enrollments'}" @click="tab='enrollments'">报名记录</button></div><span class="filter-count">{{ tab==='schedules'?selectedDate:'机构课程与报名' }}</span><button class="icon-btn" aria-label="刷新课程排课" @click="refresh"><AppIcon name="RefreshCw" :size="17" /></button></div><LoadState :loading="loading" :error="error" :empty="!(tab==='schedules'?data?.schedules:tab==='courses'?data?.courses:data?.enrollments)?.length" title="让学习从一份好安排开始" description="创建课程、完成报名后，即可安排班级教学。" @retry="refresh"><div v-if="tab==='schedules'" class="schedule-list"><article v-for="item in data?.schedules" :key="item.id" class="schedule-item"><div class="schedule-time"><strong>{{ item.startTime.slice(0,5) }}</strong><span>{{ item.endTime.slice(0,5) }}</span></div><span class="schedule-line"></span><div class="schedule-content"><span class="eyebrow">{{ item.date }} · {{ item.campusName||'—' }} · {{ item.className }}</span><h3>{{ item.courseName }}</h3><p><AppIcon name="Clock3" :size="14" />{{ item.units }} 课时 <span class="badge" :class="item.enabled?'green':'gray'">{{ item.enabled?'已启用':'已停用' }}</span></p></div></article></div><div v-else class="table-wrap"><table v-if="tab==='courses'"><thead><tr><th>课程名称</th><th>所属校区</th><th>类型</th><th>单位</th><th>课程单价</th><th>预警阈值</th><th>状态</th></tr></thead><tbody><tr v-for="item in data?.courses" :key="item.id"><td><strong>{{ item.name }}</strong></td><td>{{ item.campusName||'—' }}</td><td>{{ ({EVENING:'晚辅课程',HOLIDAY:'假期课程',WEEKEND:'周末课程'} as Record<string,string>)[item.type]||item.type }}</td><td>{{ item.unit }}</td><td class="numeric">{{ money(item.price) }}</td><td>{{ item.warningThreshold }} {{ item.unit }}</td><td><span class="badge" :class="item.enabled?'green':'gray'">{{ item.enabled?'已启用':'已停用' }}</span></td></tr></tbody></table><table v-else><thead><tr><th>学生</th><th>所属校区</th><th>报名课程</th><th>课时账户</th></tr></thead><tbody><tr v-for="item in data?.enrollments" :key="item.id"><td><strong>{{ item.studentName }}</strong></td><td>{{ item.campusName||'—' }}</td><td>{{ item.courseName }}</td><td><RouterLink :to="`/ledger?studentId=${item.studentId}`" class="text-btn">账户 #{{ item.accountId }}<AppIcon name="ArrowUpRight" :size="14" /></RouterLink></td></tr></tbody></table></div></LoadState></section></template>
